// TestFramesFixture cross-checks the Go implementation against the frame fixture
// generated by the TypeScript implementation (test/interop/crh_frames.json). Every
// positive is decoded, compared with an independently hand-written expected value
// derived from doc/design/protocol.md and the entry's description, then re-encoded and
// compared with the fixture hex. Every negative must be rejected by the same decode
// path (frame and body).
func TestFramesFixture(t *testing.T) {
	path := filepath.Join("..", "..", "..", "test", "interop", "crh_frames.json")
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	var fixture struct {
		Positive []struct {
			ID          string `json:"id"`
			Description string `json:"description"`
			Hex         string `json:"hex"`
		} `json:"positive"`
		Negative []struct {
			ID          string `json:"id"`
			Description string `json:"description"`
			Hex         string `json:"hex"`
		} `json:"negative"`
	}
	if err := json.Unmarshal(data, &fixture); err != nil {
		t.Fatalf("parse %s: %v", path, err)
	}

	// The reverse direction: every hand-written expectation must also appear in the fixture,
	// so an entry that disappears cannot silently shrink the coverage.
	positive := make(map[string]bool, len(fixture.Positive))
	for _, entry := range fixture.Positive {
		positive[entry.ID] = true
	}
	for _, id := range fixtureExpectedIDs {
		if !positive[id] {
			t.Errorf("hand-written expectation %s is missing from %s", id, path)
		}
	}

	for _, entry := range fixture.Positive {
		t.Run(entry.ID, func(t *testing.T) {
			raw := mustHex(t, entry.Hex)
			got, err := decodeFixtureValue(raw, entry.ID)
			if err != nil {
				t.Fatalf("decode: %v", err)
			}
			want, ok := expectedFixtureValue(entry.ID)
			if !ok {
				t.Fatalf("no hand-written expectation for %s", entry.ID)
			}
			if !reflect.DeepEqual(got, want) {
				t.Fatalf("decoded value mismatch:\n got %#v\nwant %#v", got, want)
			}
			if isFactsBody(got) {
				// Facts is the protocol's one map: the schema value drops keys this implementation does
				// not know, so the byte-for-byte comparison is the profile's, on the generic value
				// (doc/design/protocol.md "Events").
				if err := checkProfileReencode(raw); err != nil {
					t.Fatalf("profile re-encode: %v", err)
				}
				return
			}
			encoded, err := encodeFixtureValue(got)
			if err != nil {
				t.Fatalf("re-encode: %v", err)
			}
			if got := hex.EncodeToString(encoded); got != entry.Hex {
				t.Fatalf("re-encoded as %s, want %s", got, entry.Hex)
			}
		})
	}

	for _, entry := range fixture.Negative {
		t.Run(entry.ID, func(t *testing.T) {
			if _, err := decodeFixtureValue(mustHex(t, entry.Hex), entry.ID); err == nil {
				t.Fatalf("accepted: %s", entry.Description)
			}
		})
	}
}

// fixtureFrame is a decoded frame plus its schema-typed body. Error responses carry Err
// instead of Body.
type fixtureFrame struct {
	Kind FrameKind
	ID   Uint
	Name string
	OK   bool
	Err  *Error
	Body any
}

func decodeFixtureValue(raw []byte, id string) (any, error) {
	switch {
	case strings.HasPrefix(id, "handshake.init."):
		var init HandshakeInit
		if err := Unmarshal(raw, &init); err != nil {
			return nil, err
		}
		return init, nil
	case strings.HasPrefix(id, "handshake.response."):
		var response HandshakeResponse
		if err := Unmarshal(raw, &response); err != nil {
			return nil, err
		}
		return response, nil
	}

	frame, err := DecodeFrame(raw)
	if err != nil {
		return nil, err
	}
	decoded := fixtureFrame{
		Kind: frame.Kind,
		ID:   frame.ID,
		Name: frame.Name,
		OK:   frame.OK,
		Err:  frame.Err,
	}
	if frame.Kind == FrameResponse && !frame.OK {
		return decoded, nil
	}
	body, err := decodeFixtureBody(frame)
	if err != nil {
		return nil, err
	}
	decoded.Body = body
	return decoded, nil
}

func decodeFixtureBody(frame *Frame) (any, error) {
	switch frame.Kind {
	case FrameRequest:
		switch frame.Name {
		case CmdHello:
			var v Hello
			return v, Unmarshal(frame.Body, &v)
		case CmdPing:
			var v Ping
			return v, Unmarshal(frame.Body, &v)
		case CmdTaskStart:
			var v TaskStart
			return v, Unmarshal(frame.Body, &v)
		case CmdTaskInput:
			var v TaskInput
			return v, Unmarshal(frame.Body, &v)
		case CmdTaskCancel:
			var v TaskCancel
			return v, Unmarshal(frame.Body, &v)
		case CmdTaskQuery:
			var v TaskQuery
			return v, Unmarshal(frame.Body, &v)
		case CmdLocalRequest:
			var v LocalRequest
			return v, Unmarshal(frame.Body, &v)
		case CmdLocalWithdraw:
			var v LocalWithdraw
			return v, Unmarshal(frame.Body, &v)
		}
	case FrameResponse:
		switch frame.Name {
		case CmdHello:
			var v Welcome
			return v, Unmarshal(frame.Body, &v)
		case CmdPing:
			var v Ping
			return v, Unmarshal(frame.Body, &v)
		case CmdTaskStart, CmdTaskInput, CmdTaskCancel:
			var v Empty
			return v, Unmarshal(frame.Body, &v)
		case CmdTaskQuery:
			var v TaskStatus
			return v, Unmarshal(frame.Body, &v)
		case CmdLocalWithdraw:
			var v Empty
			return v, Unmarshal(frame.Body, &v)
		case CmdLocalRequest:
			var v LocalState
			return v, Unmarshal(frame.Body, &v)
		}
	case FrameEvent:
		switch frame.Name {
		case EventTaskOutput:
			var v TaskOutput
			return v, Unmarshal(frame.Body, &v)
		case EventTaskExit:
			var v TaskExit
			return v, Unmarshal(frame.Body, &v)
		case EventFacts:
			var v Facts
			return v, Unmarshal(frame.Body, &v)
		case EventNodeStatus:
			var v NodeStatus
			return v, Unmarshal(frame.Body, &v)
		case EventOutputAck:
			var v OutputAck
			return v, Unmarshal(frame.Body, &v)
		case EventTaskExitAck:
			var v TaskExitAck
			return v, Unmarshal(frame.Body, &v)
		case EventTrustSummary:
			var v TrustReport
			return v, Unmarshal(frame.Body, &v)
		case EventLocalDecision:
			var v LocalDecision
			return v, Unmarshal(frame.Body, &v)
		}
	}
	return nil, fmt.Errorf("no body type for frame kind %d name %q", frame.Kind, frame.Name)
}

// isFactsBody reports whether a decoded fixture value is an event frame whose body is Facts.
func isFactsBody(value any) bool {
	frame, ok := value.(fixtureFrame)
	if !ok || frame.Kind != FrameEvent || frame.Name != EventFacts {
		return false
	}
	_, ok = frame.Body.(Facts)
	return ok
}

// checkProfileReencode verifies that the strict profile decoder reproduces raw byte for byte. That
// is the comparison Unmarshal applies to a Facts body, where the schema value loses unknown keys.
func checkProfileReencode(raw []byte) error {
	value, err := decodeAny(raw)
	if err != nil {
		return err
	}
	encoded, err := encMode.Marshal(value)
	if err != nil {
		return err
	}
	if !bytes.Equal(encoded, raw) {
		return fmt.Errorf("re-encoded as %x", encoded)
	}
	return nil
}

func encodeFixtureValue(value any) ([]byte, error) {
	switch v := value.(type) {
	case HandshakeInit:
		return Marshal(v)
	case HandshakeResponse:
		return Marshal(v)
	case fixtureFrame:
		switch {
		case v.Kind == FrameRequest:
			return EncodeRequest(v.ID, v.Name, v.Body)
		case v.Kind == FrameResponse && v.OK:
			return EncodeResponse(v.ID, v.Name, v.Body)
		case v.Kind == FrameResponse:
			if v.Err == nil {
				return nil, fmt.Errorf("fixture %d: error response without Error", v.ID)
			}
			return EncodeErrorResponse(v.ID, v.Name, v.Err.Code, v.Err.Message)
		case v.Kind == FrameEvent:
			return EncodeEvent(v.Name, v.Body)
		}
	}
	return nil, fmt.Errorf("cannot encode fixture value %T", value)
}

// The hand-written expectations below are transcribed from doc/design/protocol.md and the
// description of each fixture entry, independently of the TypeScript generator.

// fixtureCommands is the handshake command list of the fixture, in its wire order: the
// M3.5 names followed by the M4 additions.
func fixtureCommands() []string {
	return []string{
		CmdHello, CmdPing, CmdTaskStart, CmdTaskInput, CmdTaskCancel, CmdTaskQuery,
		EventTaskOutput, EventTaskExit, EventFacts, EventNodeStatus, EventOutputAck, EventTaskExitAck,
		CmdLocalRequest, CmdLocalWithdraw, EventTrustSummary, EventLocalDecision,
	}
}

func fixtureFacts() Facts {
	return Facts{
		Hostname:        "node-1",
		OSID:            ptr("ubuntu"),
		OSVersionID:     ptr("24.04"),
		OSPrettyName:    ptr("Ubuntu 24.04 LTS"),
		Kernel:          ptr("6.8.0-31-generic"),
		Arch:            ptr("x86_64"),
		InitSystem:      ptr("systemd"),
		PackageManagers: []string{"apt", "snap"},
		PrivilegeTools:  []string{"sudo"},
		NotesPath:       ptr("/etc/crh/notes"),
		ClockOffsetMS:   ptr(Int(-1234)),
		Shells:          &Shells{Sh: "/bin/sh", Bash: ptr("/usr/bin/bash")},
	}
}

// fixtureCredentialID is the 32-byte credential id of the passkey trust entry.
func fixtureCredentialID() []byte {
	h := fixtureHash(0x11)
	return h[:]
}

func fixtureHash(value byte) Hash {
	var h Hash
	for i := range h {
		h[i] = value
	}
	return h
}

